const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const root = path.resolve(__dirname, '..');
const publicDir = path.join(root, 'public');

async function main() {
  await esbuild.build({
    entryPoints: [path.join(root, 'src', 'app.ts')],
    bundle: true,
    outfile: path.join(publicDir, 'app.js'),
    platform: 'browser',
    format: 'iife',
    globalName: 'PellmoorApp',
    target: ['es2020'],
    sourcemap: true,
    minify: false,
  });
  fs.copyFileSync(path.join(root, 'src', 'styles.css'), path.join(publicDir, 'styles.css'));
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const ROOT = path.resolve(__dirname, '..');
const SEED_PATH = '/recruitment/records/pellmoor_seed_data.json';
const PIPELINE_STAGES = ['applied', 'screening', 'interview', 'offer', 'hired'];
const TERMINAL_STAGES = ['rejected', 'withdrawn'];
const ELIGIBLE_PANEL_MEMBERS = new Set([
  'hiring@pellmoor.test',
  'panel1@pellmoor.test',
  'panel2@pellmoor.test',
]);
const ROLE_BY_EMAIL = new Map([
  ['hiring@pellmoor.test', 'hiring manager'],
  ['panel1@pellmoor.test', 'panel'],
  ['panel2@pellmoor.test', 'panel'],
  ['coord@pellmoor.test', 'coordinator'],
]);

function sha256(value) {
  return crypto.createHash('sha256').update(String(value)).digest('hex');
}

function nowIso() {
  return new Date().toISOString();
}

function parseJsonFile(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function normalizePayload(value) {
  if (Array.isArray(value)) {
    return value.map(normalizePayload);
  }
  if (value && typeof value === 'object') {
    return Object.keys(value)
      .sort()
      .reduce((acc, key) => {
        acc[key] = normalizePayload(value[key]);
        return acc;
      }, {});
  }
  return value;
}

function payloadHash(payload) {
  return sha256(JSON.stringify(normalizePayload(payload)));
}

function parsePositiveIntegerText(value) {
  if (typeof value !== 'string' || !/^\d+$/.test(value)) {
    return null;
  }
  return Number(value);
}

function allowedTargetStages(currentStage) {
  const index = PIPELINE_STAGES.indexOf(currentStage);
  if (index === -1) return [];
  const targets = new Set();
  if (PIPELINE_STAGES[index - 1]) targets.add(PIPELINE_STAGES[index - 1]);
  if (PIPELINE_STAGES[index + 1]) targets.add(PIPELINE_STAGES[index + 1]);
  targets.add('rejected');
  targets.add('withdrawn');
  return [...targets];
}

function isFrozenStage(stage) {
  return TERMINAL_STAGES.includes(stage) || stage === 'offer' || stage === 'hired';
}

function createStore(dbPath) {
  const resolvedDbPath = dbPath || process.env.DB_PATH || path.join(ROOT, 'pellmoor.db');
  const dbDir = path.dirname(resolvedDbPath);
  fs.mkdirSync(dbDir, { recursive: true });
  const db = new Database(resolvedDbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  db.pragma('busy_timeout = 5000');

  initSchema(db);
  seedIfNeeded(db);

  function getSession(token) {
    if (!token) return null;
    const tokenHash = sha256(token);
    return db
      .prepare(
        `SELECT s.token_hash, s.email, s.created_at, s.revoked_at, u.name, u.role
         FROM sessions s
         JOIN users u ON u.email = s.email
         WHERE s.token_hash = ?`
      )
      .get(tokenHash);
  }

  function createSession(email) {
    const token = crypto.randomBytes(32).toString('hex');
    const tokenHash = sha256(token);
    const createdAt = nowIso();
    db.prepare(
      'INSERT INTO sessions(token_hash, email, created_at, revoked_at) VALUES(?, ?, ?, NULL)'
    ).run(tokenHash, email, createdAt);
    return { token, createdAt };
  }

  function revokeSession(token) {
    if (!token) return false;
    const tokenHash = sha256(token);
    const result = db.prepare('UPDATE sessions SET revoked_at = ? WHERE token_hash = ? AND revoked_at IS NULL').run(nowIso(), tokenHash);
    return result.changes > 0;
  }

  function getUserByEmail(email) {
    return db.prepare('SELECT email, name, role FROM users WHERE email = ?').get(email);
  }

  function getVacancyRecord(code) {
    return db.prepare('SELECT code, title, team, openings, revision FROM vacancies WHERE code = ?').get(code);
  }

  function listVacancies() {
    const vacancyRows = db.prepare('SELECT code, title, team, openings, revision FROM vacancies ORDER BY code').all();
    return vacancyRows.map((vacancy) => summarizeVacancy(vacancy.code, vacancy));
  }

  function getBootstrap(email) {
    return {
      user: getUserByEmail(email),
      vacancies: listVacancies(),
      pipelineStages: PIPELINE_STAGES,
      terminalStages: TERMINAL_STAGES,
      panelMembers: [...ELIGIBLE_PANEL_MEMBERS].map((memberEmail) => getUserByEmail(memberEmail)).filter(Boolean),
    };
  }

  function getVacancyView(code) {
    const vacancy = getVacancyRecord(code);
    if (!vacancy) return null;
    return summarizeVacancy(code, vacancy, true);
  }

  function getCandidateView(candidateId) {
    const candidate = db
      .prepare(
        `SELECT c.id, c.vacancy_code, c.name, c.stage, c.assessment_version, c.applied_at, c.created_at, c.updated_at,
                v.title AS vacancy_title, v.team AS vacancy_team, v.openings, v.revision
         FROM candidates c
         JOIN vacancies v ON v.code = c.vacancy_code
         WHERE c.id = ?`
      )
      .get(candidateId);
    if (!candidate) return null;
    return buildCandidateDetail(candidate);
  }

  function previewBatch(vacancyCode, candidateIds) {
    const vacancy = getVacancyRecord(vacancyCode);
    if (!vacancy) return null;
    const candidateDetails = candidateIds.map((id) => getCandidateView(id));
    const currentCounts = vacancyCapacityCounts(vacancyCode);
    const projected = {
      reserved: currentCounts.reserved + candidateIds.length,
      filled: currentCounts.filled,
      available: vacancy.openings - (currentCounts.reserved + candidateIds.length + currentCounts.filled),
    };
    return {
      vacancy: summarizeVacancy(vacancyCode, vacancy, true),
      selectionCount: candidateIds.length,
      selection: candidateDetails,
      currentCapacity: currentCounts,
      projectedCapacity: projected,
    };
  }

  function createCandidate(actor, vacancyCode, name, noteText, operationId) {
    return runWriteOperation(actor, 'POST', `/api/vacancies/${vacancyCode}/candidates`, operationId, { vacancyCode, name, noteText }, () => {
      const vacancy = getVacancyRecord(vacancyCode);
      if (!vacancy) return businessReject(404, 'Vacancy not found');
      const cleanName = normalizeName(name);
      if (!cleanName) return businessReject(400, 'Candidate name is required');
      const duplicate = db
        .prepare('SELECT id FROM candidates WHERE vacancy_code = ? AND lower(name) = lower(?)')
        .get(vacancyCode, cleanName);
      if (duplicate) return businessReject(409, 'That person already exists on this vacancy');
      const candidateId = nextCandidateId();
      const createdAt = nowIso();
      const appliedAt = createdAt;
      const currentVersion = 1;
      const insertCandidate = db.prepare(
        `INSERT INTO candidates(id, vacancy_code, name, stage, assessment_version, applied_at, created_at, updated_at, created_by)
         VALUES(?, ?, ?, 'applied', ?, ?, ?, ?, ?)`
      );
      insertCandidate.run(candidateId, vacancyCode, cleanName, currentVersion, appliedAt, createdAt, createdAt, actor.email);
      insertStageHistory({
        candidateId,
        vacancyCode,
        stage: 'applied',
        actorEmail: actor.email,
        reason: 'candidate created',
        assessmentVersion: currentVersion,
      });
      insertActivity({
        vacancyCode,
        candidateId,
        actorEmail: actor.email,
        type: 'candidate-created',
        title: `Added ${cleanName}`,
        body: `Created at applied stage`,
        revision: vacancy.revision + 1,
        details: {
          candidateId,
          stage: 'applied',
          assessmentVersion: currentVersion,
        },
      });
      if (noteText && String(noteText).trim()) {
        insertNote({
          actorEmail: actor.email,
          vacancyCode,
          candidateId,
          text: String(noteText).trim(),
        });
      }
      bumpVacancyRevision(vacancyCode);
      return success(201, { vacancy: getVacancyView(vacancyCode), candidate: getCandidateView(candidateId) });
    });
  }

  function changeStage(actor, candidateId, nextStage, operationId) {
    return runWriteOperation(actor, 'POST', `/api/candidates/${candidateId}/stage`, operationId, { candidateId, nextStage }, () => {
      const candidate = getCandidateForUpdate(candidateId);
      if (!candidate) return businessReject(404, 'Candidate not found');
      const vacancy = getVacancyRecord(candidate.vacancy_code);
      if (!vacancy) return businessReject(404, 'Vacancy not found');
      if (actor.role !== 'hiring manager') return businessReject(403, 'Only Ruth may move candidates');
      if (candidate.stage === nextStage) return businessReject(409, 'Candidate is already at that stage');
      if (TERMINAL_STAGES.includes(candidate.stage)) return businessReject(409, 'Terminal applications cannot be moved');
      if (![...PIPELINE_STAGES, ...TERMINAL_STAGES].includes(nextStage)) return businessReject(400, 'Unknown stage');

      const currentIndex = PIPELINE_STAGES.indexOf(candidate.stage);
      const nextIndex = PIPELINE_STAGES.indexOf(nextStage);
      const terminalMove = TERMINAL_STAGES.includes(nextStage);
      const legalStep = terminalMove || nextIndex === currentIndex - 1 || nextIndex === currentIndex + 1;
      if (!legalStep) return businessReject(409, 'Stage jumps are not allowed');

      const releasesOpening = candidate.stage === 'offer' || candidate.stage === 'hired';
      const takesOpening = nextStage === 'offer';
      const movesIntoInterview = nextStage === 'interview' && candidate.stage !== 'interview';
      const beforeVersion = candidate.assessment_version;
      const afterVersion = movesIntoInterview ? beforeVersion + 1 : beforeVersion;
      const currentRevision = vacancy.revision;

      if (candidate.stage === 'hired' && nextStage === 'interview') {
        return businessReject(409, 'Use hired to offer first, then offer to interview');
      }

      if (takesOpening) {
        const capacity = vacancyCapacityCounts(vacancy.code);
        if (capacity.available <= 0 && candidate.stage !== 'hired') {
          return businessReject(409, 'Vacancy is full');
        }
      }

      if (releasesOpening) {
        releaseOpening(candidate.stage, nextStage);
      }

      db.prepare('UPDATE candidates SET stage = ?, assessment_version = ?, updated_at = ? WHERE id = ?').run(nextStage, afterVersion, nowIso(), candidateId);
      insertStageHistory({
        candidateId,
        vacancyCode: vacancy.code,
        stage: nextStage,
        actorEmail: actor.email,
        reason: stageReason(candidate.stage, nextStage),
        assessmentVersion: afterVersion,
      });
      insertActivity({
        vacancyCode: vacancy.code,
        candidateId,
        actorEmail: actor.email,
        type: 'stage-change',
        title: `${candidate.name}: ${candidate.stage} → ${nextStage}`,
        body: movesIntoInterview ? `Assessment version advanced to ${afterVersion}` : `Stage updated without changing assessment version`,
        revision: currentRevision + 1,
        details: {
          fromStage: candidate.stage,
          toStage: nextStage,
          assessmentVersionBefore: beforeVersion,
          assessmentVersionAfter: afterVersion,
          assessmentVersionChanged: movesIntoInterview,
        },
      });
      bumpVacancyRevision(vacancy.code);
      return success(200, { vacancy: getVacancyView(vacancy.code), candidate: getCandidateView(candidateId) });
    });
  }

  function changePanel(actor, candidateId, memberEmail, action, operationId) {
    return runWriteOperation(actor, 'POST', `/api/candidates/${candidateId}/panel`, operationId, { candidateId, memberEmail, action }, () => {
      const candidate = getCandidateForUpdate(candidateId);
      if (!candidate) return businessReject(404, 'Candidate not found');
      const vacancy = getVacancyRecord(candidate.vacancy_code);
      if (!vacancy) return businessReject(404, 'Vacancy not found');
      if (actor.role !== 'coordinator') return businessReject(403, 'Only Cal may change panels');
      if (!['applied', 'screening', 'interview'].includes(candidate.stage)) {
        return businessReject(409, 'Panels are frozen at offer, hired, rejected and withdrawn');
      }
      if (!ELIGIBLE_PANEL_MEMBERS.has(memberEmail)) return businessReject(409, 'That person cannot be assigned to a panel');
      if (memberEmail === 'coord@pellmoor.test') return businessReject(409, 'Cal cannot be assigned to a panel');
      const currentActive = getActivePanelMembers(candidateId);
      const alreadyActive = currentActive.includes(memberEmail);
      if (action === 'add' && alreadyActive) return businessReject(409, 'That panel member is already assigned');
      if (action === 'remove' && !alreadyActive) return businessReject(409, 'That panel member is not assigned');
      const beforeVersion = candidate.assessment_version;
      const afterVersion = beforeVersion + 1;
      if (action === 'add') {
        db.prepare(
          `INSERT INTO candidate_panels(candidate_id, vacancy_code, member_email, active, added_by, added_at, removed_by, removed_at)
           VALUES(?, ?, ?, 1, ?, ?, NULL, NULL)
           ON CONFLICT(candidate_id, member_email) DO UPDATE SET active = 1, added_by = excluded.added_by, added_at = excluded.added_at, removed_by = NULL, removed_at = NULL`
        ).run(candidateId, vacancy.code, memberEmail, actor.email, nowIso());
      } else {
        db.prepare(
          `UPDATE candidate_panels SET active = 0, removed_by = ?, removed_at = ? WHERE candidate_id = ? AND member_email = ?`
        ).run(actor.email, nowIso(), candidateId, memberEmail);
      }
      db.prepare('UPDATE candidates SET assessment_version = ?, updated_at = ? WHERE id = ?').run(afterVersion, nowIso(), candidateId);
      insertStageHistory({
        candidateId,
        vacancyCode: vacancy.code,
        stage: candidate.stage,
        actorEmail: actor.email,
        reason: action === 'add' ? `panel member ${memberEmail} added` : `panel member ${memberEmail} removed`,
        assessmentVersion: afterVersion,
      });
      insertActivity({
        vacancyCode: vacancy.code,
        candidateId,
        actorEmail: actor.email,
        type: action === 'add' ? 'panel-add' : 'panel-remove',
        title: `${action === 'add' ? 'Added' : 'Removed'} panel member`,
        body: `${memberLabel(memberEmail)} ${action === 'add' ? 'assigned to' : 'removed from'} the panel`,
        revision: vacancy.revision + 1,
        details: {
          memberEmail,
          action,
          assessmentVersionBefore: beforeVersion,
          assessmentVersionAfter: afterVersion,
        },
      });
      bumpVacancyRevision(vacancy.code);
      return success(200, { vacancy: getVacancyView(vacancy.code), candidate: getCandidateView(candidateId) });
    });
  }

  function recordScore(actor, candidateId, score, operationId) {
    return runWriteOperation(actor, 'POST', `/api/candidates/${candidateId}/scores`, operationId, { candidateId, score }, () => {
      const candidate = getCandidateForUpdate(candidateId);
      if (!candidate) return businessReject(404, 'Candidate not found');
      const vacancy = getVacancyRecord(candidate.vacancy_code);
      if (!vacancy) return businessReject(404, 'Vacancy not found');
      if (candidate.stage !== 'interview') return businessReject(409, 'Scores can only be recorded at interview');
      if (!ELIGIBLE_PANEL_MEMBERS.has(actor.email)) return businessReject(403, 'Only panel members may score');
      const activePanel = getActivePanelMembers(candidateId);
      if (!activePanel.includes(actor.email)) return businessReject(403, 'Only assigned panel members may score');
      if (!Number.isInteger(score) || score < 1 || score > 5) return businessReject(400, 'Scores must be whole numbers from 1 to 5');
      const version = candidate.assessment_version;
      const existing = db
        .prepare('SELECT score FROM candidate_scores WHERE candidate_id = ? AND assessment_version = ? AND member_email = ?')
        .get(candidateId, version, actor.email);
      db.prepare(
        `INSERT INTO candidate_scores(candidate_id, vacancy_code, assessment_version, member_email, score, recorded_by, recorded_at)
         VALUES(?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(candidate_id, assessment_version, member_email)
         DO UPDATE SET score = excluded.score, recorded_by = excluded.recorded_by, recorded_at = excluded.recorded_at`
      ).run(candidateId, vacancy.code, version, actor.email, score, actor.email, nowIso());
      insertActivity({
        vacancyCode: vacancy.code,
        candidateId,
        actorEmail: actor.email,
        type: existing ? 'score-updated' : 'score-recorded',
        title: `${memberLabel(actor.email)} scored ${score}`,
        body: `Assessment version ${version} now records a ${score} from ${memberLabel(actor.email)}`,
        revision: vacancy.revision + 1,
        details: {
          memberEmail: actor.email,
          score,
          assessmentVersion: version,
          updated: Boolean(existing),
        },
      });
      bumpVacancyRevision(vacancy.code);
      return success(200, { vacancy: getVacancyView(vacancy.code), candidate: getCandidateView(candidateId) });
    });
  }

  function addNote(actor, candidateId, text, operationId) {
    return runWriteOperation(actor, 'POST', `/api/candidates/${candidateId}/notes`, operationId, { candidateId, text }, () => {
      const candidate = getCandidateForUpdate(candidateId);
      if (!candidate) return businessReject(404, 'Candidate not found');
      const vacancy = getVacancyRecord(candidate.vacancy_code);
      if (!vacancy) return businessReject(404, 'Vacancy not found');
      const cleanText = normalizeNote(text);
      if (!cleanText) return businessReject(400, 'Note text is required');
      const noteId = insertNote({
        actorEmail: actor.email,
        vacancyCode: vacancy.code,
        candidateId,
        text: cleanText,
      });
      insertActivity({
        vacancyCode: vacancy.code,
        candidateId,
        actorEmail: actor.email,
        type: 'note',
        title: `Note added`,
        body: cleanText,
        revision: vacancy.revision + 1,
        details: { noteId },
      });
      bumpVacancyRevision(vacancy.code);
      return success(201, { vacancy: getVacancyView(vacancy.code), candidate: getCandidateView(candidateId) });
    });
  }

  function batchPreview(actor, vacancyCode, candidateIds) {
    if (actor.role !== 'hiring manager') {
      return businessReject(403, 'Only Ruth may review batch offers');
    }
    const vacancy = getVacancyRecord(vacancyCode);
    if (!vacancy) return businessReject(404, 'Vacancy not found');
    const selection = candidateIds.map((id) => getCandidateView(id));
    if (selection.some((item) => !item)) return businessReject(404, 'One or more candidates were not found');
    const currentCapacity = vacancyCapacityCounts(vacancyCode);
    const projectedCapacity = {
      reserved: currentCapacity.reserved + candidateIds.length,
      filled: currentCapacity.filled,
      available: vacancy.openings - currentCapacity.reserved - currentCapacity.filled - candidateIds.length,
    };
    return success(200, {
      vacancy: summarizeVacancy(vacancyCode, vacancy, true),
      selectionCount: candidateIds.length,
      selection: selection.map((candidate) => {
        const eligibility = evaluateOfferEligibility(candidate, vacancy);
        return {
          id: candidate.id,
          name: candidate.name,
          assessmentVersion: candidate.assessmentVersion,
          stage: candidate.stage,
          eligible: eligibility.ok,
          reasons: eligibility.reasons,
        };
      }),
      currentCapacity,
      projectedCapacity,
    }, false);
  }

  function confirmBatch(actor, vacancyCode, candidateIds, operationId) {
    return runWriteOperation(actor, 'POST', `/api/vacancies/${vacancyCode}/batch-offers`, operationId, { vacancyCode, candidateIds }, () => {
      if (actor.role !== 'hiring manager') return businessReject(403, 'Only Ruth may confirm batch offers');
      const vacancy = getVacancyRecord(vacancyCode);
      if (!vacancy) return businessReject(404, 'Vacancy not found');
      if (!Array.isArray(candidateIds) || candidateIds.length === 0) return businessReject(400, 'Select at least one candidate');
      if (candidateIds.some((id) => typeof id !== 'string' || !id.trim())) return businessReject(400, 'Candidate identifiers must be non-empty strings');
      if (new Set(candidateIds).size !== candidateIds.length) return businessReject(409, 'Duplicate candidate identifiers are not allowed');
      const currentCapacity = vacancyCapacityCounts(vacancyCode);
      if (candidateIds.length > currentCapacity.available) return businessReject(409, 'Vacancy does not have enough available openings');

      const selected = candidateIds.map((id) => getCandidateForUpdate(id));
      if (selected.some((candidate) => !candidate)) return businessReject(404, 'One or more candidates were not found');
      if (selected.some((candidate) => candidate.vacancy_code !== vacancyCode)) return businessReject(409, 'All candidates must belong to the selected vacancy');
      const stagingProblem = selected.find((candidate) => candidate.stage !== 'interview');
      if (stagingProblem) return businessReject(409, `${stagingProblem.name} is not at interview`);
      for (const candidate of selected) {
        const eligibility = evaluateOfferEligibility(candidate, vacancy);
        if (!eligibility.ok) return businessReject(409, `${candidate.name} is not eligible for offer: ${eligibility.reasons.join('; ')}`);
      }
      const batchId = crypto.randomUUID();
      const currentRevision = vacancy.revision;
      const now = nowIso();
      selected.forEach((candidate, index) => {
        db.prepare('UPDATE candidates SET stage = ?, updated_at = ? WHERE id = ?').run('offer', now, candidate.id);
        insertStageHistory({
          candidateId: candidate.id,
          vacancyCode,
          stage: 'offer',
          actorEmail: actor.email,
          reason: 'batch offer confirmed',
          assessmentVersion: candidate.assessmentVersion,
          batchId,
          batchPosition: index + 1,
          batchSize: selected.length,
        });
        insertActivity({
          vacancyCode,
          candidateId: candidate.id,
          actorEmail: actor.email,
          type: 'batch-offer',
          title: `${candidate.name} offered in batch ${batchId}`,
          body: `Batch offer ${index + 1} of ${selected.length}`,
          revision: currentRevision + 1,
          batchId,
          batchPosition: index + 1,
          batchSize: selected.length,
          details: {
            candidateId: candidate.id,
            assessmentVersion: candidate.assessmentVersion,
            batchId,
            batchPosition: index + 1,
            batchSize: selected.length,
            toStage: 'offer',
          },
        });
      });
      bumpVacancyRevision(vacancyCode);
      return success(200, {
        vacancy: getVacancyView(vacancyCode),
        batchId,
        selection: selected.map((candidate, index) => ({
          id: candidate.id,
          name: candidate.name,
          position: index + 1,
          total: selected.length,
        })),
      });
    });
  }

  function runWriteOperation(actor, method, route, operationId, payload, handler) {
    const cleanOperationId = normalizeOperationId(operationId);
    if (!cleanOperationId) return businessReject(400, 'Operation id is required', false);
    const hash = payloadHash({ method, route, payload });
    const existing = db
      .prepare(
        `SELECT status_code, response_json, payload_hash
         FROM operations
         WHERE actor_email = ? AND operation_id = ? AND method = ? AND route = ?`
      )
      .get(actor.email, cleanOperationId, method, route);
    if (existing) {
      if (existing.payload_hash !== hash) {
        return businessReject(409, 'That retry identity was already used for different input');
      }
      return storedResult(existing.status_code, existing.response_json);
    }
    const tx = db.transaction(() => {
      const repeat = db
        .prepare(
          `SELECT status_code, response_json, payload_hash
           FROM operations
           WHERE actor_email = ? AND operation_id = ? AND method = ? AND route = ?`
        )
        .get(actor.email, cleanOperationId, method, route);
      if (repeat) {
        if (repeat.payload_hash !== hash) {
          return storedResult(409, JSON.stringify({ error: 'That retry identity was already used for different input' }));
        }
        return storedResult(repeat.status_code, repeat.response_json);
      }
      const result = handler();
      if (result.storeReceipt !== false) {
        db.prepare(
          `INSERT INTO operations(actor_email, operation_id, method, route, payload_hash, status_code, response_json, created_at)
           VALUES(?, ?, ?, ?, ?, ?, ?, ?)`
        ).run(actor.email, cleanOperationId, method, route, hash, result.statusCode, JSON.stringify(result.body), nowIso());
      }
      return result;
    });
    return tx();
  }

  function success(statusCode, body, storeReceipt = true) {
    return { statusCode, body, storeReceipt };
  }

  function storedResult(statusCode, responseJson) {
    return { statusCode: Number(statusCode), body: JSON.parse(responseJson), storeReceipt: false, replay: true };
  }

  function businessReject(statusCode, message, storeReceipt = true) {
    return success(statusCode, { error: message }, storeReceipt);
  }

  function normalizeName(name) {
    if (typeof name !== 'string') return '';
    return name.trim().replace(/\s+/g, ' ');
  }

  function normalizeNote(text) {
    if (typeof text !== 'string') return '';
    return text.trim();
  }

  function normalizeOperationId(operationId) {
    if (typeof operationId !== 'string') return '';
    const trimmed = operationId.trim();
    return trimmed.length ? trimmed : '';
  }

  function nextCandidateId() {
    const tx = db.transaction(() => {
      const current = db.prepare('SELECT value FROM counters WHERE name = ?').get('candidate_seq');
      const next = current ? Number(current.value) + 1 : 110;
      db.prepare(
        `INSERT INTO counters(name, value) VALUES('candidate_seq', ?) ON CONFLICT(name) DO UPDATE SET value = excluded.value`
      ).run(next);
      return `CAND-${next}`;
    });
    return tx();
  }

  function getCandidateForUpdate(candidateId) {
    return db
      .prepare(
        `SELECT c.id, c.vacancy_code, c.name, c.stage, c.assessment_version, c.applied_at, c.created_at, c.updated_at,
                v.openings, v.revision
         FROM candidates c
         JOIN vacancies v ON v.code = c.vacancy_code
         WHERE c.id = ?`
      )
      .get(candidateId);
  }

  function insertStageHistory({ candidateId, vacancyCode, stage, actorEmail, reason, assessmentVersion, batchId = null, batchPosition = null, batchSize = null }) {
    db.prepare(
      `INSERT INTO candidate_stage_history(candidate_id, vacancy_code, stage, actor_email, reason, assessment_version, batch_id, batch_position, batch_size, created_at)
       VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).run(candidateId, vacancyCode, stage, actorEmail, reason, assessmentVersion, batchId, batchPosition, batchSize, nowIso());
  }

  function insertNote({ actorEmail, vacancyCode, candidateId, text }) {
    const result = db.prepare(
      `INSERT INTO candidate_notes(candidate_id, vacancy_code, actor_email, text, created_at)
       VALUES(?, ?, ?, ?, ?)`
    ).run(candidateId, vacancyCode, actorEmail, text, nowIso());
    return result.lastInsertRowid;
  }

  function insertActivity({ vacancyCode, candidateId = null, actorEmail, type, title, body, revision, batchId = null, batchPosition = null, batchSize = null, details = {} }) {
    db.prepare(
      `INSERT INTO activity_events(vacancy_code, candidate_id, actor_email, type, title, body, revision, batch_id, batch_position, batch_size, created_at, details_json)
       VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).run(vacancyCode, candidateId, actorEmail, type, title, body, revision, batchId, batchPosition, batchSize, nowIso(), JSON.stringify(details));
  }

  function bumpVacancyRevision(vacancyCode) {
    db.prepare('UPDATE vacancies SET revision = revision + 1 WHERE code = ?').run(vacancyCode);
  }

  function releaseOpening(currentStage, nextStage) {
    if (currentStage === 'offer' || currentStage === 'hired') {
      if (nextStage !== 'offer' && nextStage !== 'hired') {
        return true;
      }
    }
    return false;
  }

  function stageReason(fromStage, toStage) {
    if (TERMINAL_STAGES.includes(toStage)) return `moved to ${toStage}`;
    if (toStage === 'interview' && fromStage !== 'interview') return 'entered interview';
    if (fromStage === 'offer' && toStage === 'hired') return 'accepted offer';
    if (fromStage === 'hired' && toStage === 'offer') return 'returned from hired to offer';
    return `moved from ${fromStage} to ${toStage}`;
  }

  function getActivePanelMembers(candidateId) {
    return db
      .prepare('SELECT member_email FROM candidate_panels WHERE candidate_id = ? AND active = 1 ORDER BY member_email')
      .all(candidateId)
      .map((row) => row.member_email);
  }

  function getPanelRows(candidateId) {
    return db
      .prepare(
        `SELECT member_email, active, added_by, added_at, removed_by, removed_at
         FROM candidate_panels
         WHERE candidate_id = ?
         ORDER BY member_email`
      )
      .all(candidateId);
  }

  function getCurrentScores(candidateId, version) {
    return db
      .prepare(
        `SELECT member_email, score, recorded_by, recorded_at
         FROM candidate_scores
         WHERE candidate_id = ? AND assessment_version = ?
         ORDER BY member_email`
      )
      .all(candidateId, version);
  }

  function getHistoricalScores(candidateId, currentVersion) {
    return db
      .prepare(
        `SELECT assessment_version, member_email, score, recorded_by, recorded_at
         FROM candidate_scores
         WHERE candidate_id = ? AND assessment_version < ?
         ORDER BY assessment_version DESC, member_email`
      )
      .all(candidateId, currentVersion);
  }

  function getNotes(candidateId) {
    return db
      .prepare(
        `SELECT id, actor_email, text, created_at
         FROM candidate_notes
         WHERE candidate_id = ?
         ORDER BY id ASC`
      )
      .all(candidateId);
  }

  function getActivity(vacancyCode, candidateId = null) {
    if (candidateId) {
      return db
        .prepare(
          `SELECT id, vacancy_code, candidate_id, actor_email, type, title, body, revision, batch_id, batch_position, batch_size, created_at, details_json
           FROM activity_events
           WHERE vacancy_code = ? AND candidate_id = ?
           ORDER BY id ASC`
        )
        .all(vacancyCode, candidateId)
        .map(formatActivity);
    }
    return db
      .prepare(
        `SELECT id, vacancy_code, candidate_id, actor_email, type, title, body, revision, batch_id, batch_position, batch_size, created_at, details_json
         FROM activity_events
         WHERE vacancy_code = ?
         ORDER BY id DESC
         LIMIT 50`
      )
      .all(vacancyCode)
      .map(formatActivity)
      .reverse();
  }

  function formatActivity(row) {
    return {
      id: row.id,
      vacancyCode: row.vacancy_code,
      candidateId: row.candidate_id,
      actorEmail: row.actor_email,
      type: row.type,
      title: row.title,
      body: row.body,
      revision: row.revision,
      batchId: row.batch_id,
      batchPosition: row.batch_position,
      batchSize: row.batch_size,
      createdAt: row.created_at,
      details: JSON.parse(row.details_json || '{}'),
    };
  }

  function summarizeVacancy(code, vacancyRow, includeCandidates = false) {
    const candidates = db
      .prepare(
        `SELECT id, name, stage, assessment_version, applied_at, created_at, updated_at
         FROM candidates
         WHERE vacancy_code = ?
         ORDER BY
           CASE stage
             WHEN 'applied' THEN 1
             WHEN 'screening' THEN 2
             WHEN 'interview' THEN 3
             WHEN 'offer' THEN 4
             WHEN 'hired' THEN 5
             WHEN 'rejected' THEN 6
             WHEN 'withdrawn' THEN 7
             ELSE 99
           END,
           id`
      )
      .all(code);
    const capacity = vacancyCapacityCounts(code, candidates);
    const funnel = buildFunnel(code, candidates);
    const summaries = candidates.map((candidate) => buildCandidateSummary(candidate));
    const activity = getActivity(code);
    const vacancy = {
      code: vacancyRow.code,
      title: vacancyRow.title,
      team: vacancyRow.team,
      openings: vacancyRow.openings,
      revision: vacancyRow.revision,
      capacity,
      funnel,
      candidateCount: candidates.length,
      activity,
      summary: {
        pipelineCount: candidates.filter((candidate) => PIPELINE_STAGES.includes(candidate.stage)).length,
        terminalCount: candidates.filter((candidate) => TERMINAL_STAGES.includes(candidate.stage)).length,
      },
    };
    if (includeCandidates) {
      vacancy.candidates = summaries;
    }
    return vacancy;
  }

  function buildCandidateSummary(candidateRow) {
    const activePanel = getActivePanelMembers(candidateRow.id);
    const currentScores = getCurrentScores(candidateRow.id, candidateRow.assessment_version);
    const historicalScores = getHistoricalScores(candidateRow.id, candidateRow.assessment_version);
    const capacity = vacancyCapacityCounts(candidateRow.vacancy_code);
    const eligibility = evaluateOfferEligibility({
      id: candidateRow.id,
      name: candidateRow.name,
      stage: candidateRow.stage,
      assessmentVersion: candidateRow.assessment_version,
      activePanel,
      currentScores,
    }, getVacancyRecord(candidateRow.vacancy_code), capacity);
    return {
      id: candidateRow.id,
      name: candidateRow.name,
      stage: candidateRow.stage,
      assessmentVersion: candidateRow.assessment_version,
      appliedAt: candidateRow.applied_at,
      updatedAt: candidateRow.updated_at,
      activePanel,
      currentScoreCount: currentScores.length,
      historicalScoreCount: historicalScores.length,
      offerReady: eligibility.ok,
      blockedReasons: eligibility.reasons,
      currentScores,
      historicalScores: groupHistoricalScores(historicalScores),
      noteCount: getNotes(candidateRow.id).length,
    };
  }

  function buildCandidateDetail(candidateRow) {
    const activePanel = getActivePanelMembers(candidateRow.id);
    const candidatePanel = getPanelRows(candidateRow.id);
    const currentScores = getCurrentScores(candidateRow.id, candidateRow.assessment_version);
    const historicalScores = getHistoricalScores(candidateRow.id, candidateRow.assessment_version);
    const notes = getNotes(candidateRow.id);
    const activity = getActivity(candidateRow.vacancy_code, candidateRow.id);
    const vacancy = getVacancyRecord(candidateRow.vacancy_code);
    const capacity = vacancyCapacityCounts(candidateRow.vacancy_code);
    const eligibility = evaluateOfferEligibility({
      id: candidateRow.id,
      name: candidateRow.name,
      stage: candidateRow.stage,
      assessmentVersion: candidateRow.assessment_version,
      activePanel,
      currentScores,
    }, vacancy, capacity);
    return {
      id: candidateRow.id,
      name: candidateRow.name,
      stage: candidateRow.stage,
      assessmentVersion: candidateRow.assessment_version,
      vacancy: {
        code: candidateRow.vacancy_code,
        title: candidateRow.vacancy_title,
        team: candidateRow.vacancy_team,
        openings: candidateRow.openings,
        revision: candidateRow.revision,
      },
      appliedAt: candidateRow.applied_at,
      createdAt: candidateRow.created_at,
      updatedAt: candidateRow.updated_at,
      stageHistory: db
        .prepare(
          `SELECT stage, actor_email, reason, assessment_version, batch_id, batch_position, batch_size, created_at
           FROM candidate_stage_history
           WHERE candidate_id = ?
           ORDER BY id ASC`
        )
        .all(candidateRow.id)
        .map((row) => ({
          stage: row.stage,
          actorEmail: row.actor_email,
          reason: row.reason,
          assessmentVersion: row.assessment_version,
          batchId: row.batch_id,
          batchPosition: row.batch_position,
          batchSize: row.batch_size,
          createdAt: row.created_at,
        })),
      activePanel,
      panelAssignments: candidatePanel.map((row) => ({
        memberEmail: row.member_email,
        active: Boolean(row.active),
        addedBy: row.added_by,
        addedAt: row.added_at,
        removedBy: row.removed_by,
        removedAt: row.removed_at,
      })),
      currentScores,
      historicalScores: groupHistoricalScores(historicalScores),
      notes,
      activity,
      offer: {
        ready: eligibility.ok,
        blockedReasons: eligibility.reasons,
      },
      canScore: activePanel.includes(candidateRow.vacancy_code === 'ROLE-014' ? 'hiring@pellmoor.test' : ''),
      capacity,
    };
  }

  function groupHistoricalScores(rows) {
    const grouped = new Map();
    for (const row of rows) {
      if (!grouped.has(row.assessment_version)) grouped.set(row.assessment_version, []);
      grouped.get(row.assessment_version).push({
        memberEmail: row.member_email,
        score: row.score,
        recordedBy: row.recorded_by,
        recordedAt: row.recorded_at,
      });
    }
    return [...grouped.entries()].map(([assessmentVersion, scores]) => ({
      assessmentVersion,
      scores,
    }));
  }

  function vacancyCapacityCounts(vacancyCode, candidateRows = null) {
    const rows = candidateRows || db
      .prepare('SELECT id, stage FROM candidates WHERE vacancy_code = ?')
      .all(vacancyCode);
    const reserved = rows.filter((row) => row.stage === 'offer').length;
    const filled = rows.filter((row) => row.stage === 'hired').length;
    const vacancy = getVacancyRecord(vacancyCode);
    const available = vacancy ? Math.max(0, vacancy.openings - reserved - filled) : 0;
    return { reserved, filled, available };
  }

  function buildFunnel(vacancyCode, candidateRows) {
    const histories = db
      .prepare(
        `SELECT candidate_id, stage, created_at
         FROM candidate_stage_history
         WHERE vacancy_code = ?
         ORDER BY id ASC`
      )
      .all(vacancyCode);
    const byCandidate = new Map();
    for (const row of histories) {
      if (!byCandidate.has(row.candidate_id)) byCandidate.set(row.candidate_id, []);
      byCandidate.get(row.candidate_id).push(row.stage);
    }
    const reached = new Map(PIPELINE_STAGES.map((stage) => [stage, new Set()]));
    const remain = new Map(PIPELINE_STAGES.map((stage) => [stage, 0]));
    const lost = new Map(PIPELINE_STAGES.map((stage) => [stage, 0]));
    for (const candidate of candidateRows) {
      const history = byCandidate.get(candidate.id) || [];
      const uniqueVisited = new Set(history.filter((stage) => PIPELINE_STAGES.includes(stage)));
      for (const stage of uniqueVisited) reached.get(stage).add(candidate.id);
      if (PIPELINE_STAGES.includes(candidate.stage)) {
        remain.set(candidate.stage, remain.get(candidate.stage) + 1);
      }
      if (TERMINAL_STAGES.includes(candidate.stage)) {
        const lastPipeline = [...history].reverse().find((stage) => PIPELINE_STAGES.includes(stage));
        if (lastPipeline) lost.set(lastPipeline, lost.get(lastPipeline) + 1);
      }
    }
    return PIPELINE_STAGES.map((stage) => ({
      stage,
      reached: reached.get(stage).size,
      remain: remain.get(stage),
      lost: lost.get(stage),
    }));
  }

  function evaluateOfferEligibility(candidate, vacancy, capacity = null) {
    const reasons = [];
    if (!candidate || !vacancy) {
      return { ok: false, reasons: ['Missing candidate or vacancy'] };
    }
    if (candidate.stage !== 'interview') reasons.push('Candidate is not at interview');
    const activePanel = candidate.activePanel || getActivePanelMembers(candidate.id);
    const panelValid = isPanelValid(activePanel);
    if (!panelValid) reasons.push('Panel is not complete');
    const currentScores = candidate.currentScores || getCurrentScores(candidate.id, candidate.assessmentVersion);
    if (activePanel.some((memberEmail) => !currentScores.find((row) => row.member_email === memberEmail))) {
      reasons.push('Current panel scores are incomplete');
    }
    const cap = capacity || vacancyCapacityCounts(vacancy.code);
    if (cap.available <= 0) reasons.push('Vacancy is full');
    return { ok: reasons.length === 0, reasons };
  }

  function isPanelValid(activePanel) {
    const members = new Set(activePanel);
    if (members.size < 2) return false;
    if (members.size === 1 && members.has('hiring@pellmoor.test')) return false;
    if (members.size >= 2 && members.has('hiring@pellmoor.test') && members.size === 1) return false;
    if (members.size >= 2 && [...members].every((member) => member === 'hiring@pellmoor.test')) return false;
    if (members.size >= 2 && members.size === 1) return false;
    if (members.size >= 2 && [...members].filter((member) => member !== 'hiring@pellmoor.test').length === 0) return false;
    return true;
  }

  function memberLabel(email) {
    const user = getUserByEmail(email);
    return user ? `${user.name} (${email})` : email;
  }

  return {
    db,
    getSession,
    createSession,
    revokeSession,
    getUserByEmail,
    getBootstrap,
    getVacancyView,
    getCandidateView,
    listVacancies,
    createCandidate,
    changeStage,
    changePanel,
    recordScore,
    addNote,
    batchPreview,
    confirmBatch,
    parsePositiveIntegerText,
  };
}

function initSchema(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS metadata (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS users (
      email TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      role TEXT NOT NULL,
      password_hash TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS sessions (
      token_hash TEXT PRIMARY KEY,
      email TEXT NOT NULL,
      created_at TEXT NOT NULL,
      revoked_at TEXT,
      FOREIGN KEY(email) REFERENCES users(email)
    );
    CREATE TABLE IF NOT EXISTS vacancies (
      code TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      team TEXT NOT NULL,
      openings INTEGER NOT NULL,
      revision INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS candidates (
      id TEXT PRIMARY KEY,
      vacancy_code TEXT NOT NULL,
      name TEXT NOT NULL,
      stage TEXT NOT NULL,
      assessment_version INTEGER NOT NULL,
      applied_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      created_by TEXT NOT NULL,
      FOREIGN KEY(vacancy_code) REFERENCES vacancies(code)
    );
    CREATE TABLE IF NOT EXISTS candidate_stage_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      candidate_id TEXT NOT NULL,
      vacancy_code TEXT NOT NULL,
      stage TEXT NOT NULL,
      actor_email TEXT NOT NULL,
      reason TEXT NOT NULL,
      assessment_version INTEGER NOT NULL,
      batch_id TEXT,
      batch_position INTEGER,
      batch_size INTEGER,
      created_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS candidate_panels (
