function seedIfNeeded(db) {
  const existing = db.prepare('SELECT value FROM metadata WHERE key = ?').get('seed_complete');
  if (existing) return;
  const seed = parseJsonFile(SEED_PATH);
  const seededAt = seed.clock || nowIso();
  const passwordHash = sha256(seed.seed_password);
  const tx = db.transaction(() => {
    for (const person of seed.people) {
      db.prepare(
        'INSERT INTO users(email, name, role, password_hash) VALUES(?, ?, ?, ?)'
      ).run(person.email, person.name, person.role, passwordHash);
    }
    for (const role of seed.roles) {
      db.prepare(
        'INSERT INTO vacancies(code, title, team, openings, revision, created_at) VALUES(?, ?, ?, ?, 1, ?)'
      ).run(role.code, role.title, role.team, role.openings, seededAt);
    }
    const seq = db.prepare('INSERT INTO counters(name, value) VALUES(?, ?)').run('candidate_seq', 109);
    for (const candidate of seed.candidates) {
      const currentVersion = 1;
      const createdAt = timeOffset(seededAt, candidate.days_since_applied, 0);
      const appliedAt = createdAt;
      db.prepare(
        `INSERT INTO candidates(id, vacancy_code, name, stage, assessment_version, applied_at, created_at, updated_at, created_by)
         VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).run(candidate.id, candidate.role, candidate.name, candidate.stage, currentVersion, appliedAt, createdAt, createdAt, 'seed');
      const history = candidate.history || [candidate.stage];
      history.forEach((stage, index) => {
        insertSeedStageHistory(db, candidate.id, candidate.role, stage, currentVersion, timeOffset(appliedAt, 0, index * 10));
        insertSeedActivity(db, candidate.role, candidate.id, 'seed', 'seed-stage', `${candidate.name}: ${stage}`, `Imported stage ${stage}`, 1, {
          stage,
          candidateId: candidate.id,
          assessmentVersion: currentVersion,
          seed: true,
        }, timeOffset(appliedAt, 0, index * 10));
      });
    }
    for (const panel of seed.panels) {
      panel.members.forEach((memberEmail) => {
        db.prepare(
          `INSERT INTO candidate_panels(candidate_id, vacancy_code, member_email, active, added_by, added_at, removed_by, removed_at)
           VALUES(?, ?, ?, 1, ?, ?, NULL, NULL)`
        ).run(panel.candidate, candidateRole(db, panel.candidate), memberEmail, 'seed', seededAt);
        insertSeedActivity(db, candidateRole(db, panel.candidate), panel.candidate, 'seed', 'seed-panel', `${panel.candidate}: panel ${memberEmail}`, `Imported panel member ${memberEmail}`, 1, {
          candidateId: panel.candidate,
          memberEmail,
          seed: true,
        }, seededAt);
      });
    }
    for (const score of seed.scores) {
      db.prepare(
        `INSERT INTO candidate_scores(candidate_id, vacancy_code, assessment_version, member_email, score, recorded_by, recorded_at)
         VALUES(?, ?, 1, ?, ?, ?, ?)`
      ).run(score.candidate, candidateRole(db, score.candidate), score.panel_member, score.score, 'seed', seededAt);
      insertSeedActivity(db, candidateRole(db, score.candidate), score.candidate, 'seed', 'seed-score', `${score.candidate}: score ${score.score}`, `Imported score ${score.score} from ${score.panel_member}`, 1, {
        candidateId: score.candidate,
        memberEmail: score.panel_member,
        score: score.score,
        assessmentVersion: 1,
        seed: true,
      }, seededAt);
    }
    db.prepare('INSERT INTO metadata(key, value) VALUES(?, ?)').run('seed_complete', '1');
  });
  tx();
}

function insertSeedStageHistory(db, candidateId, vacancyCode, stage, assessmentVersion, createdAt) {
  db.prepare(
